        )
        scores[n] = score

    # Select node with highest combined score
    next_node = max(scores, key=scores.get)
    return next_node

def select_next_node(graph, unvisited_nodes):
    pre = graph.graph['precomputed']
    avg_degree = pre['avg_degree']
    degree_variance = pre['degree_variance']
    max_core_k = pre['max_core_k']

    # Extract features
    deg = {n: graph.nodes[n]['degree'] for n in unvisited_nodes}
    bet = {n: graph.nodes[n]['betweenness'] for n in unvisited_nodes}
    clust = {n: graph.nodes[n]['clustering'] for n in unvisited_nodes}
    core = {n: graph.nodes[n]['core_number'] for n in unvisited_nodes}

    # Rank nodes (1 = highest rank)
    def rank_dict(d, reverse=True):
        sorted_nodes = sorted(d.items(), key=lambda x: x[1], reverse=reverse)
        ranks = {}
        rank_val = 1
        for node, _ in sorted_nodes:
            ranks[node] = rank_val
            rank_val += 1
        return ranks

    deg_rank = rank_dict(deg, reverse=True)           # high degree = rank 1
    bet_rank = rank_dict(bet, reverse=True)           # high betweenness = rank 1
    inv_clust = {n: 1 - clust[n] for n in unvisited_nodes}
    clust_rank = rank_dict(inv_clust, reverse=True)   # high inverse clustering = rank 1

    # Harmonic mean of ranks for each node
    import math
    def harmonic_mean(triple):
        a, b, c = triple
        return 3 / (1/a + 1/b + 1/c)

    scores = {}
    for n in unvisited_nodes:
        hmean = harmonic_mean((deg_rank[n], bet_rank[n], clust_rank[n]))
        scores[n] = hmean

    # Select node with minimal harmonic mean (best average rank)
    # Tie-break by minimal core number
    min_score = min(scores.values())
    candidates = [n for n, s in scores.items() if s == min_score]
    next_node = min(candidates, key=lambda x: core[x])

    return next_node
